#!/usr/bin/env python3
"""Prove the map markers and the key agree. Run: python3 build/test_markers.py

The markers used to be coloured dots whose colour meant "what kind of place is this" for
campgrounds and "how much do you trust this" for fuel, so amber was both "top pick" and
"unconfirmed" -- nine meanings on six colours, three of them exact duplicates. The fix
encodes category as shape, trust as fill, and a top pick as a star badge.

That only stays true if it is checked in a browser. The rules being defended:

  * the key is generated by the same code that draws the markers, so it cannot go stale
  * every legend row survives being desaturated -- the dashed ring and the diagonal strike
    are there so "unverified" and "unreachable" never depend on hue
  * 761 markers on one 469-mile road do not become a smear of overlapping glyphs
  * no marker is ever unreachable: a group that will not come apart at any zoom fans out

Skips cleanly if Playwright or Chromium is unavailable -- it is a guard, not a gate, and
build/build_app.py is what refuses to ship a page that does not parse.
"""
import json
import os
import subprocess
import sys
import tempfile

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "build"))
from test_parity import CHROME, _global_node_modules  # noqa: E402

DRIVER = r"""
const { chromium } = require('playwright');
// A flat tile in OSM's pale land colour. Real tiles need the network, and the questions
// here are about the markers, not the basemap.
const TILE = Buffer.from('89504e470d0a1a0a0000000d494844520000000100000001080200000090'
  + '773dfa0000000c4944415408d763f8cfc0f01f000501010063a0b7c800000000'
  + '49454e44ae426082', 'hex');
(async () => {
  const b = await chromium.launch({ executablePath: process.env.CHROME });
  const ctx = await b.newContext({ viewport: { width: 1280, height: 900 },
                                   permissions: ['geolocation'],
                                   geolocation: { latitude: 36.4000, longitude: -81.2000,
                                                  accuracy: 25 } });
  const p = await ctx.newPage();
  // The map instance lives inside app.js's IIFE. Rather than have the app export a global
  // purely so a test can reach it, catch the moment Leaflet assigns window.L.
  await p.addInitScript(() => {
    let real;
    Object.defineProperty(window, 'L', {
      configurable: true, get: () => real,
      set: v => {
        real = v;
        if (v && v.Map && !v.Map.__hooked) {
          v.Map.__hooked = true;
          const init = v.Map.prototype.initialize;
          v.Map.prototype.initialize = function (...a) { window.map0 = this; return init.apply(this, a); };
        }
      }
    });
  });
  await p.route('**://**', r => r.request().url().startsWith('file:')
    ? r.continue()
    : r.fulfill({ status: 200, contentType: 'image/png', body: TILE }));
  const errors = [];
  p.on('pageerror', e => errors.push(String(e)));
  await p.goto('file://' + process.env.PAGE, { waitUntil: 'domcontentloaded' });
  await p.waitForTimeout(1800);

  const wide = await p.evaluate(() => {
    map0.fitBounds(L.latLngBounds(BRP.data.parkway));
    return new Promise(res => setTimeout(() => {
      const pins = [...document.querySelectorAll('.brp-pin')];
      const clusters = [...document.querySelectorAll('.brp-cluster')];
      const boxes = [...pins, ...clusters].map(n => n.getBoundingClientRect());
      let overlaps = 0;
      for (let i = 0; i < boxes.length; i++)
        for (let j = i + 1; j < boxes.length; j++) {
          const a = boxes[i], c = boxes[j];
          if (Math.min(a.right, c.right) - Math.max(a.left, c.left) > 6 &&
              Math.min(a.bottom, c.bottom) - Math.max(a.top, c.top) > 6) overlaps++;
        }
      res({ pins: pins.length, clusters: clusters.length, overlaps,
            hidden: clusters.reduce((a, n) => a + parseInt(n.textContent, 10), 0),
            boxed: pins.filter(n => {
              const cs = getComputedStyle(n);
              return cs.backgroundColor !== 'rgba(0, 0, 0, 0)'
                  || parseFloat(cs.borderTopWidth) > 0;
            }).length });
    }, 800));
  });

  // Every state the key teaches, reduced to what survives a greyscale print.
  const grey = await p.evaluate(() => {
    const rows = [['camp', {}], ['moto', {}], ['hotel', {}], ['food', {}], ['fuel', {}],
                  ['hotel', { trust: 'listed' }], ['fuel', { trust: 'listed' }],
                  ['camp', { top: true }]];
    const sig = s => {
      const fill = s.match(/circle[^>]*fill="(#[0-9a-f]{6})"/)[1];
      const [r, g, bl] = [1, 3, 5].map(i => parseInt(fill.substr(i, 2), 16));
      return [Math.round(.2126 * r + .7152 * g + .0722 * bl),   // fill, desaturated
              /stroke-dasharray/.test(s),                        // the "listed" ring
              /translate\(23\.6,-1\.2\)/.test(s),                // the star badge
              (s.match(/translate\(6,6\)[^]*?<\/g>/) || [''])[0] // the glyph itself
             ].join('|');
    };
    const sigs = rows.map(([k, o]) => sig(pinSvg(k, o)));
    return { rows: sigs.length, distinct: new Set(sigs).size };
  });

  // Fuel that cannot be used is not drawn at all any more. MP 248.1 Laurel Springs has no
  // verifiable pump behind it; MP 344.1 NC 80 sits inside the severed section. A marker
  // whose whole content is "not this one" is not worth a glance at 60mph.
  const named = await p.evaluate(() => {
    const drawn = t => [...document.querySelectorAll('.brp-pin')].some(n => {
      const s = n.getAttribute('title') || '';
      return s.startsWith('FUEL') && s.includes(t);
    });
    const go = mp => {
      const f = BRP.data.fuel.find(x => Math.abs(x.mp - mp) < 0.3);
      map0.setView([f.parkway_lat, f.parkway_lon], 14);
    };
    go(248.1);
    return new Promise(r => setTimeout(() => {
      const a = drawn('MP 248.1');
      go(344.1);
      setTimeout(() => r({
        laurelSpringsDrawn: a, nc80Drawn: drawn('MP 344.1')
      }), 800);
    }, 800));
  });

  // The worst group on the map: every pump the Google sweep found at one exit, all
  // recorded against the same point on the Parkway. It cannot come apart by zooming.
  const stuck = await p.evaluate(() => {
    const by = {};
    BRP.data.fuel.forEach(f => {
      if (f.parkway_lat == null) return;
      const k = f.parkway_lat.toFixed(4) + ',' + f.parkway_lon.toFixed(4);
      (by[k] = by[k] || []).push(f);
    });
    const worst = Object.entries(by).sort((a, b) => b[1].length - a[1].length)[0];
    const [lat, lon] = worst[0].split(',').map(Number);
    map0.setView([lat, lon], map0.getMaxZoom() || 17);
    return new Promise(res => setTimeout(() => {
      const c = document.querySelector('.brp-cluster');
      const count = c && parseInt(c.textContent, 10);
      if (c) c.click();
      setTimeout(() => res({
        group: worst[1].length, clustered: !!c, count,
        fanned: document.querySelectorAll('.brp-pin').length,
        leaders: document.querySelectorAll('#map path[stroke="#93a8b4"]').length
      }), 700);
    }, 800));
  });

  // Selection may scale and glow; it may never restate trust in a different colour.
  const sel = await p.evaluate(() => {
    map0.fitBounds(L.latLngBounds(BRP.data.parkway));
    return new Promise(res => setTimeout(() => {
      const n = [...document.querySelectorAll('.brp-pin')].find(x => x.getAttribute('title'));
      const before = n.querySelector('circle').getAttribute('fill');
      n.click();
      setTimeout(() => {
        const s = document.querySelector('.brp-pin.is-selected');
        const cs = s && getComputedStyle(s.querySelector('svg'));
        res({ found: !!s, before, after: s && s.querySelector('circle').getAttribute('fill'),
              transform: cs && cs.transform, filter: cs && cs.filter });
      }, 800);
    }, 700));
  });

  // The fuel that IS drawn has to separate researched from merely listed. Sampled at an
  // exit that is actually on the map, not at one of the two that are excluded.
  await p.evaluate(() => {
    // A researched exit that does NOT share its Parkway anchor with other pumps. MP 0
    // Rockfish Gap has thirteen stations on one point, so it is a cluster at every zoom
    // and proves nothing about how a single fuel pin is drawn.
    window.__loneFuel = () => {
      const at = {};
      BRP.data.fuel.forEach(f => { if (f.parkway_lat != null)
        at[f.parkway_lat.toFixed(4)] = (at[f.parkway_lat.toFixed(4)] || 0) + 1; });
      return BRP.data.fuel.find(f => f.plan_grade === 'usable' && f.parkway_lat != null
                                     && at[f.parkway_lat.toFixed(4)] === 1);
    };
  });
  const fuelFills = await p.evaluate(() => {
    map0.closePopup();   // bound with keepInView -- it pans the map back under a setView
    const f = window.__loneFuel();
    map0.setView([f.parkway_lat, f.parkway_lon], 14);
    return new Promise(res => setTimeout(() => res(
      [...document.querySelectorAll('.brp-pin')]
        .filter(n => (n.getAttribute('title') || '').startsWith('FUEL'))
        .map(n => n.querySelector('circle').getAttribute('fill'))), 800));
  });

  // The category rows are switches. Flipping one has to change the map, and survive the
  // reload -- a filter that forgets itself is worse than no filter.
  const toggle = await p.evaluate(() => {
    map0.closePopup();
    const f = window.__loneFuel();
    map0.setView([f.parkway_lat, f.parkway_lon], 14);
    const shapes = n => {
      const seen = {};
      [...document.querySelectorAll('.brp-pin')].forEach(x => {
        const t = x.getAttribute('title') || '';
        const k = t.startsWith('FUEL') ? 'fuel' : 'place';
        seen[k] = (seen[k] || 0) + 1;
      });
      return seen;
    };
    return new Promise(res => setTimeout(() => {
      const before = shapes();
      const row = document.querySelector('.key-row[data-shape="fuel"]');
      row.click();
      setTimeout(() => {
        const after = shapes();
        const off = document.querySelector('.key-row[data-shape="fuel"]');
        res({ before, after, marked: off.getAttribute('aria-checked'),
              dimmed: off.classList.contains('off'),
              faded: parseFloat(getComputedStyle(off).opacity) < 0.9,
              stored: JSON.parse(localStorage.getItem('brp-trip-v2') || '{}').mapShow });
      }, 600);
    }, 800));
  });

  // Where the rider is. The Parkway has no house numbers and phone signal disappears for
  // miles, but the GPS chip does not need the network -- so this is the one live thing on
  // the map that keeps working where everything else stops.
  const gpsOff = await p.evaluate(() => ({
    hasButton: !!document.querySelector('#gpsbtn'),
    hidden: document.querySelector('#gpsbtn').hidden,
    markers: document.querySelectorAll('.brp-me').length
  }));
  const gps = await p.evaluate(() => {
    map0.closePopup();
    document.querySelector('#gpsbtn').click();
    return new Promise(res => setTimeout(() => {
      const me = document.querySelector('.brp-me');
      const c = map0.getCenter();
      res({
        marker: !!me,
        magenta: !!me && me.innerHTML.includes('#e86ec4'),
        // the motorcycle glyph, not a category pin
        moto: !!me && me.innerHTML.includes('cx="5.1"'),
        ring: !!document.querySelector('#map path[stroke="#e86ec4"]'),
        followed: Math.abs(c.lat - 36.4) < 0.02 && Math.abs(c.lng + 81.2) < 0.02,
        pressed: document.querySelector('#gpsbtn').getAttribute('aria-pressed'),
        following: document.querySelector('#gpsbtn').classList.contains('following')
      });
    }, 1200));
  });
  // Panning by hand must stop the map chasing the rider, or looking ahead is impossible.
  const panned = await p.evaluate(() => {
    map0.fire('dragstart');
    return new Promise(res => setTimeout(() => res({
      following: document.querySelector('#gpsbtn').classList.contains('following'),
      stillTracking: document.querySelector('#gpsbtn').classList.contains('on'),
      marker: !!document.querySelector('.brp-me')
    }), 300));
  });
  // Tap once to resume following, again to switch it off entirely.
  const stopped = await p.evaluate(() => {
    document.querySelector('#gpsbtn').click();          // resume following
    return new Promise(res => setTimeout(() => {
      const resumed = document.querySelector('#gpsbtn').classList.contains('following');
      document.querySelector('#gpsbtn').click();        // off
      setTimeout(() => res({
        resumed, marker: !!document.querySelector('.brp-me'),
        pressed: document.querySelector('#gpsbtn').getAttribute('aria-pressed'),
        stored: JSON.parse(localStorage.getItem('brp-trip-v2') || '{}').gps
      }), 400);
    }, 400));
  });

  // The notch. env(safe-area-inset-*) cannot be emulated in a desktop Chromium, so the
  // inset is injected at the same place the real rule applies it and the consequence is
  // what gets checked: with a 59px status bar, nothing interactive may sit under it, and
  // nothing may gain a SECOND inset further down the page.
  const INSET = 59;
  // #maptoggle only exists below 860px -- it is the phone-only map/list swap -- so this
  // has to be measured at phone size or the very control that failed is display:none.
  await p.setViewportSize({ width: 390, height: 844 });
  const safeArea = await p.evaluate(inset => {
    const st = document.createElement('style');
    // Override the shared name, exactly where the real notch feeds in. Overriding #app's
    // padding alone would miss every position:fixed control -- which is most of them.
    st.textContent = `:root { --safe-top: ${inset}px; }`;
    document.head.append(st);
    // A phone: the map is the top element, so its controls are the ones at risk.
    document.querySelector('#app').classList.add('map-full');
    return new Promise(res => setTimeout(() => {
      const boxes = {};
      for (const [name, sel] of [['maptoggle', '#maptoggle'], ['gps', '#gpsbtn'],
                                 ['zoom', '.leaflet-control-zoom'], ['key', '.legend']]) {
        const n = document.querySelector(sel);
        boxes[name] = n ? n.getBoundingClientRect().top : null;
      }
      const header = document.querySelector('header');
      res({ boxes,
            headerPadTop: parseFloat(getComputedStyle(header).paddingTop),
            appBottom: document.querySelector('#app').getBoundingClientRect().bottom,
            viewport: window.innerHeight,
            scroll: document.documentElement.scrollHeight - window.innerHeight });
    }, 500));
  }, INSET);
  // The map/list swap has to work in BOTH directions. "Show the list" collapses the map
  // pane to height zero, and the button used to live inside it -- clipped away with it,
  // leaving no way back to the map at all.
  const swap = await p.evaluate(() => {
    const app = document.querySelector('#app');
    app.classList.remove('map-full');
    const btn = document.querySelector('#maptoggle');
    btn.click();                                    // -> full map
    const mapFull = app.className;
    btn.click();                                    // -> list
    return new Promise(res => setTimeout(() => {
      const b = document.querySelector('#maptoggle');
      const r = b.getBoundingClientRect();
      const mid = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
      res({ mapFull, listFull: app.className,
            visible: r.width > 0 && r.height > 0,
            onTop: !!(mid && mid.closest('#maptoggle')),
            hit: mid ? (mid.id || mid.className || mid.tagName) : null,
            label: b.textContent });
    }, 400));
  });
  await p.evaluate(() => {
    const app = document.querySelector('#app');
    app.classList.remove('map-full', 'list-full');
    [...document.querySelectorAll('style')].pop().remove();
  });
  await p.setViewportSize({ width: 1280, height: 900 });

  /* Half and half is the default and has to be reachable again.
   *
   * The toggle used to flip between the two FULL views only, so the first tap locked the
   * rider out of the split view for the rest of the session. And in the full list, tapping
   * a place only opened a card on the map -- a card that, by definition, is not on screen.
   */
  await p.setViewportSize({ width: 390, height: 844 });
  // An earlier check left the view somewhere; wind it round to the split view first, so
  // the cycle is recorded from a known starting point rather than wherever it landed.
  await p.evaluate(() => {
    const btn = document.querySelector('#maptoggle');
    for (let i = 0; i < 3 && btn.textContent !== 'Full map'; i++) btn.click();
  });
  await p.waitForTimeout(300);
  const viewCycle = [];
  for (let i = 0; i < 4; i++) {
    viewCycle.push(await p.evaluate(() => ({
      view: document.querySelector('#app').className.match(/map-full|list-full/)
              ? document.querySelector('#app').className.match(/map-full|list-full/)[0]
              : 'split',
      label: document.querySelector('#maptoggle').textContent,
    })));
    await p.evaluate(() => document.querySelector('#maptoggle').click());
    await p.waitForTimeout(280);
  }

  const listAdd = await p.evaluate(() => {
    const app = document.querySelector('#app');
    let guard = 0;
    while (!app.classList.contains('list-full') && guard++ < 5) {
      document.querySelector('#maptoggle').click();
    }
    document.querySelector('.tabs button[data-tab="browse"]').click();
    return new Promise(res => setTimeout(() => {
      const row = document.querySelector('#pane-browse .scroller .row');
      if (!row) return res({ noRow: true });
      const name = row.querySelector('.name').textContent;
      row.click();
      setTimeout(() => {
        const act = document.querySelector('#pane-browse .rowact');
        const labels = act ? [...act.querySelectorAll('button')].map(x => x.textContent) : [];
        // The button must be a real sibling of the row, not nested inside it: a <button>
        // inside a <button> is markup browsers quietly unpick.
        const nested = !!(act && act.closest('.row'));
        if (act) act.querySelector('button').click();
        setTimeout(() => res({
          name, labels, nested,
          view: app.className.match(/list-full/) ? 'list-full' : 'other',
          stops: (JSON.parse(localStorage.getItem('brp-trip-v2') || '{}').stops || [])
                   .map(x => x.name),
        }), 700);
      }, 500);
    }, 600));
  });
  await p.evaluate(() => {
    const app = document.querySelector('#app');
    app.classList.remove('map-full', 'list-full');
  });
  await p.setViewportSize({ width: 1280, height: 900 });

  const key = await p.evaluate(() => ({
    heads: [...document.querySelectorAll('.key-head')].map(n => n.textContent),
    rows: document.querySelectorAll('.key-row').length,
    switches: document.querySelectorAll('.key-row[data-shape]').length,
    swatches: document.querySelectorAll('.key-icon svg').length,
    footer: (document.querySelector('.key-footer') || {}).textContent || '',
    route: LINE.yourRoute.color,
    magentaMarkers: [...document.querySelectorAll('.brp-pin')]
      .filter(n => n.innerHTML.toLowerCase().includes(LINE.yourRoute.color.slice(1))).length
  }));

  console.log(JSON.stringify({ wide, grey, named, fuelFills, stuck, sel, toggle,
                               gpsOff, gps, panned, stopped, safeArea, swap,
                               viewCycle, listAdd, key, errors }));
  await b.close();
})();
"""

failures = []


def check(name, ok, detail=""):
    print(f"  {'pass' if ok else 'FAIL'}  {name}" + ("" if ok else f"   {detail}"))
    if not ok:
        failures.append(name)


def main():
    if not os.path.exists(CHROME):
        print("skip: chromium not available")
        return 0
    page = os.path.join(ROOT, "index.html")
    if not os.path.exists(page):
        print("skip: index.html not built")
        return 0
    scratch = os.environ.get("SCRATCH", tempfile.gettempdir())
    driver = os.path.join(scratch, "marker_driver.js")
    with open(driver, "w") as f:
        f.write(DRIVER)
    env = {**os.environ, "CHROME": CHROME, "PAGE": page,
           "NODE_PATH": os.pathsep.join(
               [os.path.join(scratch, "node_modules"), *_global_node_modules()])}
    try:
        raw = subprocess.run(["node", driver], capture_output=True, text=True,
                             env=env, timeout=180, cwd=scratch)
    except Exception as e:
        print(f"skip: could not drive the browser ({e})")
        return 0
    if raw.returncode != 0:
        print("skip: browser run failed\n" + raw.stderr[-500:])
        return 0
    js = json.loads(raw.stdout.strip().splitlines()[-1])

    # How many markers there should be, from the data rather than from a number typed here.
    with open(os.path.join(ROOT, "data", "derived", "browser-data.json")) as f:
        data = json.load(f)
    drawable = [f for f in data["fuel"]
                if f["plan_grade"] not in ("unreachable", "do_not_rely") and f.get("stations")]
    total = len(data["places"]) + len(drawable)

    print("the key is drawn by the same code as the markers")
    key = js["key"]
    check("the key is grouped by what you can do with it",
          key["heads"] == ["SHOW ON THE MAP", "HOW MUCH TO TRUST IT", "LINES"],
          str(key["heads"]))
    check("every key row draws a real swatch, none are hand-written",
          key["rows"] == key["swatches"] and key["rows"] >= 14,
          f"{key['rows']} rows, {key['swatches']} swatches")
    check("the footer says the rows can be tapped", "Tap a row" in key["footer"],
          key["footer"][:60])
    check("every category is a switch", key["switches"] == 5, str(key["switches"]))

    print("\nthe encoding survives being desaturated")
    check("no two key states collapse into each other in greyscale",
          js["grey"]["distinct"] == js["grey"]["rows"],
          f"{js['grey']['distinct']} distinct of {js['grey']['rows']}")

    print("\n761 markers on one road stay readable")
    wide = js["wide"]
    check("Leaflet's white divIcon box is overridden on every pin", wide["boxed"] == 0,
          f"{wide['boxed']} boxed")
    check("the whole Parkway does not draw every glyph at once", wide["pins"] < 60,
          f"{wide['pins']} pins")
    check("no two markers sit on top of one another", wide["overlaps"] == 0,
          f"{wide['overlaps']} overlapping pairs")
    check("every marker is accounted for, as a pin or inside a count",
          wide["pins"] + wide["hidden"] == total,
          f"{wide['pins']}+{wide['hidden']} != {total}")

    print("\nno marker is unreachable")
    stuck = js["stuck"]
    check("markers sharing one coordinate are clustered, not stacked", stuck["clustered"],
          json.dumps(stuck))
    check("a group that no zoom can separate fans out when tapped",
          stuck["fanned"] >= stuck["count"], json.dumps(stuck))
    check("each fanned marker keeps a line back to where it really is",
          stuck["leaders"] == stuck["count"], json.dumps(stuck))

    print("\nunusable fuel is not on the map at all")
    named = js["named"]
    check("an exit with no verifiable pump is not drawn",
          not named["laurelSpringsDrawn"], json.dumps(named))
    check("an exit inside a severed section is not drawn",
          not named["nc80Drawn"], json.dumps(named))
    check("the fuel that is drawn is green when researched, grey when only listed",
          bool(js["fuelFills"]) and set(js["fuelFills"]) <= {"#35d07f", "#93a8b4"},
          str(sorted(set(js["fuelFills"]))))

    print("\nselection does not lie about trust")
    sel = js["sel"]
    check("a tapped marker is marked selected", sel["found"], json.dumps(sel))
    check("and keeps its fill, because fill means trust", sel["before"] == sel["after"],
          f"{sel['before']} -> {sel['after']}")
    check("it scales and glows instead",
          "matrix" in (sel["transform"] or "") and "drop-shadow" in (sel["filter"] or ""),
          f"{sel['transform']} / {sel['filter']}")

    print("\nlines and markers do not share a hue")
    check("the planned route is magenta", key["route"].lower() == "#e86ec4", key["route"])
    # The live position marker is deliberately magenta -- "you" and "your route" are meant
    # to match. What must never be magenta is a place or a pump, which is what this counts.
    check("and no place or fuel pin is", key["magentaMarkers"] == 0,
          str(key["magentaMarkers"]))

    print("\nthe key doubles as the map's controls")
    tg = js["toggle"]
    check("the map has fuel on it to begin with", tg["before"].get("fuel", 0) > 0,
          json.dumps(tg["before"]))
    check("tapping the fuel row takes every fuel pin off the map",
          tg["after"].get("fuel", 0) == 0, json.dumps(tg["after"]))
    check("and leaves the other shapes alone",
          tg["after"].get("place", 0) == tg["before"].get("place", 0),
          json.dumps(tg))
    check("the row says it is off, for a screen reader too", tg["marked"] == "false",
          str(tg["marked"]))
    check("and looks off, which a second class attribute had been silently dropping",
          tg["dimmed"] and tg["faded"], json.dumps(tg))
    check("and the choice is remembered", tg["stored"] and tg["stored"]["fuel"] is False,
          json.dumps(tg["stored"]))

    print("\nthe rider's own position")
    check("the map carries a locate control", js["gpsOff"]["hasButton"]
          and not js["gpsOff"]["hidden"], json.dumps(js["gpsOff"]))
    check("nothing is drawn until it is asked for", js["gpsOff"]["markers"] == 0,
          json.dumps(js["gpsOff"]))
    g = js["gps"]
    check("a fix puts the rider on the map", g["marker"], json.dumps(g))
    check("as a motorcycle, not a category pin", g["moto"], json.dumps(g))
    check("in the route's magenta, so 'you' and 'your ride' match", g["magenta"],
          json.dumps(g))
    check("with an accuracy circle, so a loose fix does not look precise", g["ring"],
          json.dumps(g))
    check("and the map moves to them", g["followed"], json.dumps(g))
    check("the control says it is on", g["pressed"] == "true" and g["following"],
          json.dumps(g))
    pan = js["panned"]
    check("panning by hand stops the map chasing them", not pan["following"],
          json.dumps(pan))
    check("but tracking carries on", pan["stillTracking"] and pan["marker"],
          json.dumps(pan))
    st = js["stopped"]
    check("tapping again resumes following", st["resumed"], json.dumps(st))
    check("and once more switches it off", not st["marker"] and st["pressed"] == "false",
          json.dumps(st))
    check("which is remembered as off", st["stored"] is False, json.dumps(st))

    print("\nnothing hides behind the notch")
    sa = js["safeArea"]
    inset = 59
    for name, top in sa["boxes"].items():
        check(f"the {name} control clears the status bar",
              top is not None and top >= inset, f"top {top} < {inset}")
    # The header used to add the inset a second time. On a phone it sits below the map, so
    # that opened a band of empty panel in the middle of the screen, above the logo.
    check("the header does not inset itself a second time", sa["headerPadTop"] < 20,
          f"{sa['headerPadTop']}px of top padding")
    check("and the inset does not push the shell off the bottom of the screen",
          sa["appBottom"] <= sa["viewport"] + 1 and sa["scroll"] <= 1,
          json.dumps({k: sa[k] for k in ("appBottom", "viewport", "scroll")}))

    print("\nhalf and half is reachable, and the list can add a stop by itself")
    vc = js["viewCycle"]
    check("it cycles split, full map, full list, and back to split",
          [v["view"] for v in vc] == ["split", "map-full", "list-full", "split"],
          str([v["view"] for v in vc]))
    check("and each label names what the next tap gives you",
          [v["label"] for v in vc[:3]] == ["Full map", "Full list", "Split view"],
          str([v["label"] for v in vc]))
    la = js["listAdd"]
    check("a row in the full list offers the action itself",
          bool(la.get("labels")), json.dumps(la))
    check("the action is a sibling of the row, not a button inside a button",
          not la.get("nested"), json.dumps(la))
    check("tapping it adds the place without ever showing the map",
          la.get("stops") == [la.get("name")] and la.get("view") == "list-full",
          json.dumps(la))

    print("\nthe map/list swap is not a one-way door")
    sw = js["swap"]
    check("showing the full map works", "map-full" in sw["mapFull"], sw["mapFull"])
    check("showing the list works", "list-full" in sw["listFull"], sw["listFull"])
    check("the way back to the map still has a size", sw["visible"], json.dumps(sw))
    check("and is actually on top, not clipped by the collapsed map pane", sw["onTop"],
          json.dumps(sw))
    # Under the three-state cycle the way out of the full list is the split view, which is
    # a view WITH the map in it. What must never happen is the list offering another list.
    check("and it offers a view that contains the map",
          sw["label"] in ("Full map", "Split view"), sw["label"])

    check("the page raised no errors", not js["errors"], str(js["errors"][:3]))

    print()
    if failures:
        print(f"{len(failures)} FAILED: {failures}")
        return 1
    print("map markers and the key agree, and every marker is reachable")
    return 0


if __name__ == "__main__":
    sys.exit(main())
